(() => {
  const STAMP='2026-09-18T10:00:00+02:00', CUTOFF='2026-05-18';
  const CHECKED=new Set(['HNR1','EUNL','LHA','ALV']), CHANGED=new Set(['LHA','ALV']);
  const sleep=ms=>new Promise(r=>setTimeout(r,ms));
  const fmt=v=>new Intl.DateTimeFormat('de-DE',{timeZone:'Europe/Berlin',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(v)).replace(',',' ·');
  async function ready(){for(let i=0;i<80;i++){try{if(Array.isArray(holdings)&&holdings.length===12&&typeof renderCards==='function'&&typeof renderDetail==='function')return true}catch(_){}await sleep(250)}return false}
  function apply(){window.marketAgentUpdateMeta={contentUpdatedAt:STAMP,lastSuccessfulRunAt:STAMP,status:'partial',marketStatus:'open',holdingsFallback:true};holdings.forEach(h=>{if(!CHECKED.has(h.id))return;h.analysts=(h.analysts||[]).filter(x=>!/^\d{4}-\d{2}-\d{2}$/.test(x.date)||x.date>=CUTOFF);h.insiders=(h.insiders||[]).filter(x=>!/^\d{4}-\d{2}-\d{2}$/.test(x.date)||x.date>=CUTOFF);h.lastCheckedAt=STAMP;h.changedSections=[];h.updateStatus='checked';delete h.updateTag});
    const hnr=holdings.find(h=>h.id==='HNR1');if(hnr){hnr.analystNote='Rollierendes Vier-Monats-Fenster ab 18.05.2026, geprüft bis 18.09.2026 10:00 CEST. Keine neue belastbar verifizierte Einzelrevision seit dem vorherigen EU-Lauf.';hnr.insiderNote='Rollierendes Vier-Monats-Fenster ab 18.05.2026 geprüft; keine neue relevante diskretionäre Open-Market-Transaktion verifiziert.'}
    const etf=holdings.find(h=>h.id==='EUNL');if(etf){etf.analystNote='Nicht anwendbar: ETF. ISIN IE00B4L5Y983; Analysten- und Insiderfelder sind für ETFs nicht anwendbar.';etf.insiderNote='Nicht anwendbar: Ein ETF hat keine Unternehmensinsider.'}
    const lha=holdings.find(h=>h.id==='LHA');if(lha){lha.news=lha.news||[];if(!lha.news.some(n=>n.title&&n.title.includes('20 Boeing 737 MAX 10')))lha.news.unshift({date:'2026-09-17',sourceName:'Lufthansa Group',category:'Flotte',title:'NEU · 20 Boeing 737 MAX 10 aus bestehenden Optionen fest bestellt',summary:'Der Aufsichtsrat genehmigte die Ausübung von 20 Kaufoptionen. Das 737-MAX-Bestellvolumen steigt auf 60 Flugzeuge; Auslieferungen der MAX 10 sollen Anfang der 2030er beginnen. Lufthansa nennt rund 30 % weniger Treibstoffverbrauch gegenüber den zu ersetzenden älteren Flugzeugen und rund 20 % niedrigere Stückkosten.',impact:1,impactText:'Langfristig positiv für Flotteneffizienz und Stückkosten; kurzfristig begrenzter Ergebnisimpuls wegen später Auslieferung.',source:'https://newsroom.lufthansagroup.com/en/lufthansa-group-expands-boeing-737-max-fleet/'});lha.changedSections=['news','tailwinds'];lha.lastChangedAt=STAMP;lha.updateStatus='changed';lha.tailwinds=lha.tailwinds||[];if(!lha.tailwinds.some(x=>x.includes('737 MAX 10')))lha.tailwinds.unshift('20 zusätzliche Boeing 737 MAX 10 stärken langfristig Flotteneffizienz und Kapazitätsplanung; Auslieferung ab Anfang der 2030er.');}
    const alv=holdings.find(h=>h.id==='ALV');if(alv){alv.news=alv.news||[];if(!alv.news.some(n=>n.title&&n.title.includes('Scaleup Europe Fund')))alv.news.unshift({date:'2026-09-17',sourceName:'Allianz',category:'Investment',title:'NEU · Allianz beteiligt sich am Scaleup Europe Fund',summary:'Allianz Leben, Allianz Private Krankenversicherung und Allianz France investieren Kundengelder in den europäischen Scaleup Europe Fund für Wachstumsunternehmen in strategischen Technologiesektoren.',impact:1,impactText:'Leicht positiver strategischer Impuls durch Ausbau langfristiger Wachstumsanlagen; kurzfristig kein wesentlicher Ergebniseffekt quantifiziert.',source:'https://www.allianz.com/en/mediacenter/news/media-releases/260917-allianz-invests-in-european-growth-fund.html'});alv.changedSections=['news'];alv.lastChangedAt=STAMP;alv.updateStatus='changed';}}
  function mark(){const c=document.getElementById('content-state-chip'),t=document.getElementById('content-state');if(c&&t){t.textContent=`Inhalte: ${fmt(STAMP)}`;c.classList.remove('status-ok','status-partial','status-error','status-closed');c.classList.add('status-partial');c.title='Holdings-Datei nicht erreichbar – letzter bestätigter Bestand verwendet.'}document.querySelectorAll('.holding').forEach(x=>{x.classList.remove('content-changed','content-partial');if(CHANGED.has(x.dataset.id))x.classList.add('content-changed');if(CHECKED.has(x.dataset.id))x.title=CHANGED.has(x.dataset.id)?`Letzte Inhaltsänderung: ${fmt(STAMP)}`:`Letzte Inhaltsprüfung: ${fmt(STAMP)} · Keine inhaltliche Änderung`});const f=document.querySelector('footer.shell');if(f)f.textContent='Market Agent · Datenstand 18.09.2026 · 10:00 · Quellen in jedem Eintrag'}
  async function boot(){if(!(await ready()))return;apply();renderCards();renderDetail();mark();[1500,5000,13000,20000].forEach(ms=>setTimeout(()=>{try{renderCards();renderDetail();mark()}catch(_){}},ms));document.addEventListener('click',e=>{if(e.target.closest('.holding,.tab,.filter'))setTimeout(mark,0)});window.addEventListener('pageshow',()=>setTimeout(mark,250))}boot();
})();
